const lessons=window.LESSONS;
const $=s=>document.querySelector(s);
const escapeText=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const key='asteroids-learning-v1';let state={done:{},notes:{},last:null};let storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&typeof saved==='object')state={done:saved.done||{},notes:saved.notes||{},last:saved.last||null};}catch{storageAvailable=false;}
let view={lesson:null,step:0,all:false};let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500);}
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{storageAvailable=false;toast('Хранилище недоступно. Скачай заметки, чтобы сохранить их.');return false;}}
const stepKey=(l,i)=>`${l.id}:${i}`;
const completed=l=>l.sections.filter((_,i)=>state.done[stepKey(l,i)]).length;
function renderNav(){
 $('#lessons-nav').innerHTML=lessons.map(l=>`<a class="nav-item ${view.lesson===l.id?'active':''}" href="#lesson/${l.id}/0" ${view.lesson===l.id?'aria-current="page"':''}><span class="nav-number">0${l.id}</span><span>${l.title}</span><span class="nav-check">${completed(l)===l.sections.length?'✓':''}</span></a>`).join('');
 const total=lessons.reduce((n,l)=>n+l.sections.length,0),done=lessons.reduce((n,l)=>n+completed(l),0);$('#total-progress').textContent=`${done} / ${total}`;$('#total-bar').style.width=`${done/total*100}%`;
}
function home(){
 const current=state.last&&lessons.find(l=>l.id===state.last.lesson);const focus=current||lessons[5];const at=current?Math.min(state.last.step,focus.sections.length-1):0;
 $('#crumb').textContent='Карта обучения';
 $('#main').innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">УЧИМСЯ НА СВОЁМ ПРОЕКТЕ</div><h1>Разобраться.<br>Собрать. <em>Проверить.</em></h1><p>Замечания ментора — в понятные шаги. Исследуй свой код, проверяй гипотезы и приходи к решению самостоятельно.</p><div class="meta-row"><span>6 занятий</span><span>Unity + C#</span><span>В своём темпе</span></div></div><div class="orbit-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="asteroid">{ }</div><i class="orbit-dot"></i></div></section><section class="focus-card"><div><div class="eyebrow">${current?'ПРОДОЛЖИТЬ С МЕСТА ОСТАНОВКИ':'СЕЙЧАС В ФОКУСЕ'}</div><h2>${focus.title}</h2><p>${current?escapeText(focus.sections[at].title):'Почему Presenter знает слишком много — и как отделить кнопки, данные и правила игры.'}</p></div><a class="primary" href="#lesson/${focus.id}/${at}">${current?'Продолжить':'Разобрать Presenter'} <span>↗</span></a></section><div class="section-heading"><h2>Твой учебный маршрут</h2><span>Можно проходить по порядку или выбрать тему</span></div><div class="lesson-grid">${lessons.map(l=>`<a class="lesson-card" href="#lesson/${l.id}/0"><div class="card-top"><span class="lesson-number">/ 0${l.id}</span><span class="tag">${l.tag}</span></div><h3>${l.title}</h3><p>${l.description}</p><div class="card-bottom"><span>${completed(l)?`${completed(l)} из ${l.sections.length} шагов пройдено`:`${l.sections.length} шагов · практика и подсказки`}</span><b>${completed(l)===l.sections.length?'✓':'↗'}</b></div></a>`).join('')}</div><section class="method"><div><strong><span>01</span> Сначала предположи</strong><p>Что произойдёт и почему? Запиши свой ответ до запуска.</p></div><div><strong><span>02</span> Затем проверь</strong><p>Найди место в коде. Проведи небольшой опыт в Unity.</p></div><div><strong><span>03</span> Объясни результат</strong><p>Сравни с прогнозом. Подсказку открывай после своей попытки.</p></div></section><p class="welcome-note">Материалы основаны на разборе исходников. Проверки в Unity ты выполняешь сам. <a href="downloads/README.md" download>Скачать карту обучения ↓</a></p>`;
}
function stepHTML(l,i,all=false){const s=l.sections[i],done=state.done[stepKey(l,i)];return `<article class="step-card" id="step-${i}"><div class="step-meta"><span>${/подсказ/i.test(s.title)?'ПОДСКАЗКИ · ПОСЛЕ СВОЕЙ ПОПЫТКИ':/провер|критер/i.test(s.title)?'ПРОВЕРКА ПОНИМАНИЯ':'ИССЛЕДУЙ → ПОПРОБУЙ → ОБЪЯСНИ'}</span><span>${i+1} / ${l.sections.length}</span></div><h2>${escapeText(s.title)}</h2><div class="prose">${s.html}</div><div class="step-actions"><label class="complete"><input type="checkbox" data-done="${i}" ${done?'checked':''}> Шаг пройден</label>${all?'':`<div class="pager"><button class="secondary" data-prev ${i===0?'disabled':''}>← Назад</button><button class="primary" data-next>${i===l.sections.length-1?'К маршруту':'Дальше →'}</button></div>`}</div></article>`;}
function lesson(){const l=lessons.find(x=>x.id===view.lesson);const i=view.step;const s=l.sections[i];$('#crumb').textContent=l.title;
 $('#main').innerHTML=`<div class="lesson-header"><div><div class="eyebrow">ЗАНЯТИЕ 0${l.id} <span> / </span> ${l.tag.toUpperCase()}</div><h1>${l.title}</h1><p class="lesson-description">${l.description}</p></div><a class="text-link" href="downloads/${l.file}" download>Скачать занятие ↓</a></div><div class="lesson-layout"><div class="${view.all?'all-mode':''}">${view.all?l.sections.map((_,j)=>stepHTML(l,j,true)).join(''):stepHTML(l,i)}${view.all?'':`<section class="notes"><div class="notes-header"><label for="step-note">Мои мысли и наблюдения</label><small id="save-status">${storageAvailable?'Сохраняются в браузере':'Сохранение недоступно'}</small></div><p class="note-prompt">Мой прогноз → что получилось → как я это объясняю</p><textarea id="step-note" placeholder="Не нужно писать идеально. Зафиксируй, что понял и что пока вызывает вопросы.">${escapeText(state.notes[stepKey(l,i)]||'')}</textarea></section>`}<div id="completion"></div></div><aside class="step-outline" aria-label="Шаги занятия"><p class="outline-label">СОДЕРЖАНИЕ ЗАНЯТИЯ</p><div class="outline-list">${l.sections.map((a,j)=>`<a class="outline-item ${!view.all&&j===i?'active':''} ${state.done[stepKey(l,j)]?'done':''}" href="#lesson/${l.id}/${j}" ${!view.all&&j===i?'aria-current="step"':''}><span>${state.done[stepKey(l,j)]?'✓':String(j+1).padStart(2,'0')}</span>${escapeText(a.title)}</a>`).join('')}</div><div class="outline-tools"><a class="text-link" href="#lesson/${l.id}/${view.all?i:'all'}">${view.all?'Читать по одному шагу':'Показать занятие целиком'}</a></div></aside></div>`;
 document.querySelectorAll('[data-done]').forEach(el=>el.addEventListener('change',()=>{state.done[stepKey(l,+el.dataset.done)]=el.checked;save();renderNav();const item=document.querySelectorAll('.outline-item')[+el.dataset.done];item.classList.toggle('done',el.checked);item.querySelector('span').textContent=el.checked?'✓':String(+el.dataset.done+1).padStart(2,'0');completion(l);}));
 $('[data-prev]')?.addEventListener('click',()=>location.hash=`lesson/${l.id}/${i-1}`);$('[data-next]')?.addEventListener('click',()=>location.hash=i===l.sections.length-1?'home':`lesson/${l.id}/${i+1}`);
 $('#step-note')?.addEventListener('input',e=>{state.notes[stepKey(l,i)]=e.target.value;$('#save-status').textContent=save()?'Сохранено в этом браузере':'Скачай заметки для сохранения';});
 completion(l);
}
function completion(l){$('#completion').innerHTML=completed(l)===l.sections.length?'<div class="completion-banner">✓ Все шаги отмечены. Попробуй теперь объяснить решение своими словами — это лучшая проверка.</div>':'';}
function route(){const p=location.hash.slice(1).split('/');const l=lessons.find(l=>l.id===p[1]);view={lesson:p[0]==='lesson'&&l?l.id:null,step:0,all:p[2]==='all'};if(view.lesson){view.step=Math.min(Math.max(parseInt(p[2],10)||0,0),l.sections.length-1);state.last={lesson:l.id,step:view.step};save();lesson();document.title=`${l.title} — Asteroids`;}else{home();document.title='Asteroids — учебная мастерская';}renderNav();document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);$('#main').focus({preventScroll:true});}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-copy]');if(el){try{await navigator.clipboard.writeText(el.dataset.copy);toast('Путь к файлу скопирован');}catch{const input=document.createElement('textarea');input.value=el.dataset.copy;document.body.append(input);input.select();const ok=document.execCommand('copy');input.remove();toast(ok?'Путь к файлу скопирован':'Не удалось скопировать путь');}}if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menu')){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');}});
$('#menu').addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(open));});
$('#export').addEventListener('click',()=>{let text='# Моя мастерская Asteroids\n\n';for(const l of lessons){text+=`## ${l.title}\n\n`;l.sections.forEach((s,i)=>{const note=state.notes[stepKey(l,i)];text+=`- [${state.done[stepKey(l,i)]?'x':' '}] ${s.title}\n`;if(note)text+=`\n${note}\n\n`;});text+='\n';}const u=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='asteroids-my-notes.md';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Заметки и прогресс сохранены в файл');});
function search(){const q=$('#search-input').value.trim().toLocaleLowerCase('ru');if(!q){$('#search-results').innerHTML='<p class="search-empty">Ищи по теме, имени класса или вопросу.</p>';return;}const results=[];for(const l of lessons)l.sections.forEach((s,i)=>{if((s.title+' '+s.text+' '+l.title).toLocaleLowerCase('ru').includes(q))results.push({l,s,i});});$('#search-results').innerHTML=results.length?results.slice(0,30).map(({l,s,i})=>`<a class="search-result" href="#lesson/${l.id}/${i}">${escapeText(s.title)}<small>${l.title} · шаг ${i+1}</small></a>`).join(''):'<p class="search-empty">Ничего не найдено. Попробуй другое слово.</p>';}
function openSearch(){$('#search-dialog').showModal();$('#search-input').focus();search();}
$('#search-open').addEventListener('click',openSearch);$('#search-close').addEventListener('click',()=>$('#search-dialog').close());$('#search-input').addEventListener('input',search);$('#search-results').addEventListener('click',e=>{if(e.target.closest('a'))$('#search-dialog').close();});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#search-dialog').open){e.preventDefault();openSearch();}if(e.key==='Escape'){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');}});
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();});
const narrow=matchMedia('(max-width:760px)');
function syncMenu(){const open=document.body.classList.contains('menu-open');$('#sidebar').inert=narrow.matches&&!open;}
new MutationObserver(syncMenu).observe(document.body,{attributes:true,attributeFilter:['class']});narrow.addEventListener('change',syncMenu);syncMenu();
window.addEventListener('hashchange',route);route();
